import{_ as r,o as t,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-27（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-27-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-27-ai.md"}'),e={name:"topics/ai-system-architecture/science-daily-2026-10-27-ai.md"};function i(a,o,g,c,l,d){return t(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-27-ai-系统架构" tabindex="-1">科学日报 · 2026-10-27（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-27-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-27（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> — 第46期 ｜ 🤖 AI 前沿（5 篇 arXiv，真实抓取于 2026-10-27）</p></blockquote><hr><h2 id="🧰-用「可守卫的持久决定」换-token——harnessmm-的自改进-harness-令牌效率" tabindex="-1">🧰 用「可守卫的持久决定」换 token——HarnessMM 的自改进 harness 令牌效率 <a class="header-anchor" href="#🧰-用「可守卫的持久决定」换-token——harnessmm-的自改进-harness-令牌效率" aria-label="Permalink to &quot;🧰 用「可守卫的持久决定」换 token——HarnessMM 的自改进 harness 令牌效率&quot;">​</a></h2><blockquote><p>arXiv:2610.32813 ｜ HarnessMM: Recursive Self-Improvement for Harness Token Efficiency</p></blockquote><ul><li>问题：coding agent 装在 <strong>harness</strong>（工具框架）里，harness 表现建立在<strong>每步重复的推理</strong>上，<strong>令牌开销高</strong>；而既有 harness 优化方法<strong>依赖人工启发式或额外模型调用</strong>，且<strong>单任务、难迁移</strong>。</li><li>方法：<strong>HarnessMM</strong> —— 把 <strong>harness 自改进</strong>建模为<strong>可恢复（guarded）的持久决定产物的演进</strong>：一个 <strong>decision store</strong>（持久决定存储）从一个<strong>任务无关的父 harness</strong> 共享继承；对每个任务，<strong>多智能体循环</strong>把轨迹转为<strong>候选决定的增删替换</strong>，再在<strong>留出集</strong>上用<strong>留一测试（leave-one-out）<strong>判定是否</strong>泛化</strong>（提升则接受）。</li><li>结果：<strong>TerminalBench 令牌消耗降 14%</strong>（同样是 <strong>100% 留存率</strong>）的同时<strong>通过率升 6.25%</strong>；<strong>SWE-bench Verified</strong> 上<strong>令牌降约 16%</strong>；验证环境上通过率再升 <strong>2.5%</strong> 且<strong>令牌再降 10.6%</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>ai-brain</code>）： <ol><li><strong>把「每次重复的推理」固化成「一次可复用的决定」</strong> = 从<strong>无状态</strong>走向<strong>有状态</strong>（<code>decision store</code>）。与 10-26 <code>Accordion</code>（一套参数一个深度旋钮）、10-25 <code>METTA</code>（时间尺度分解）同族：<strong>智能体效率提升的主线，是把『反复计算』改为『记住一个决定』。</strong></li><li><strong>「留一测试」做决定准入 = 与 AI 外脑 <code>auto_link.py</code> 的准入门一脉同源</strong>：<strong>改动只有在留出集上泛化才被接受</strong>，等价于本库的**「写入前先问：这条链接在别的样本上还成立吗？」** → 可写入 <code>topics/ai-brain/</code> 的「准入规则」。</li></ol></li></ul><hr><h2 id="♻️-无数据自提升——把「外部语料」换成「策略自己出的题」" tabindex="-1">♻️ 无数据自提升——把「外部语料」换成「策略自己出的题」 <a class="header-anchor" href="#♻️-无数据自提升——把「外部语料」换成「策略自己出的题」" aria-label="Permalink to &quot;♻️ 无数据自提升——把「外部语料」换成「策略自己出的题」&quot;">​</a></h2><blockquote><p>arXiv:2610.32770 ｜ On-Policy Self-Training: Data-Free Self-Improvement in Large Language Models</p></blockquote><ul><li>问题：LLM 提升常依赖<strong>外部数据</strong>（昂贵/受限）；能否用<strong>模型自己生成的数据</strong>提升自己？</li><li>方法：<strong>On-Policy Self-Training（OPST）</strong> —— 后训练框架<strong>替代外部监督</strong>：模型对<strong>自己采样的输出</strong>反复自训练；关键是<strong>模型同时生成正向与负向监督信号</strong>，把「对/错」都变成学习材料，且<strong>在自己的策略分布上</strong>（on-policy）训练。</li><li>结果：OPST <strong>显著提升指令遵循与少量样本推理</strong>：在算术推理等任务上，<strong>指令遵循准确率较基线提升最高 63%</strong>（具体数值以正文为准）；且<strong>不需要任何外部数据集</strong>。</li><li>洞察：<strong>「自己出题、自己判分」能成立的前提是『负样本也带信息』</strong> —— 与 10-22 <code>Environment Duels</code>（<strong>解题力 ≠ 出题力</strong>）、10-20 <code>Self-Building Labs</code>（自己搭实验室）同族：<strong>自提升系统的瓶颈不是『能不能自产数据』，而是『自产的数据里有没有真正的对照（负例）』。</strong> 判据：<strong>无监督自提升要有效，必须让『错』也能被定位，而不只是让『对』被强化。</strong></li></ul><hr><h2 id="📐-模态鸿沟可以「用几何压掉」——单纯形约束表征把-97-–99-的鸿沟消掉" tabindex="-1">📐 模态鸿沟可以「用几何压掉」——单纯形约束表征把 97%–99% 的鸿沟消掉 <a class="header-anchor" href="#📐-模态鸿沟可以「用几何压掉」——单纯形约束表征把-97-–99-的鸿沟消掉" aria-label="Permalink to &quot;📐 模态鸿沟可以「用几何压掉」——单纯形约束表征把 97%–99% 的鸿沟消掉&quot;">​</a></h2><blockquote><p>arXiv:2610.32890 ｜ Closing the Modality Gap via Simplex-Constrained Representations</p></blockquote><ul><li>问题：多模态模型的<strong>模态鸿沟</strong>（不同模态嵌入在共享空间中<strong>系统性分离</strong>）损害跨模态检索/对齐。</li><li>方法：<strong>单纯形约束表征</strong> —— 把嵌入约束在一个**单纯形（simplex）**上（而非球面），<strong>无需数据特定微调、无需训练</strong>即可施加；在 <strong>CLIP</strong> 与 <strong>SigLIP</strong> 模型上验证。</li><li>结果：<strong>97%–99% 的模态鸿沟被消除</strong>，且<strong>跨模态能力改善</strong>——<strong>图像分类 +6.5%</strong>、<strong>跨模态检索 +8.3%</strong>、<strong>零样本组合泛化 +5.2%</strong>。</li><li>洞察：<strong>「鸿沟」可能不是语义差异，而是几何投影的伪影</strong> —— 与 10-23「概念擦除与引导是同一算子的两面」、10-21「隐喻的几何」同族：<strong>当两个空间『看起来分开』，先问是不是表征的坐标系选错了，而不是急着用数据去拉近它们。</strong> 可迁移判据：<strong>『对齐问题』常常可以重写成『几何约束问题』——后者零训练。</strong></li></ul><hr><h2 id="🔬-可解释的稀疏微调——topklora-让「后门电路」自己现形" tabindex="-1">🔬 可解释的稀疏微调——TopKLoRA 让「后门电路」自己现形 <a class="header-anchor" href="#🔬-可解释的稀疏微调——topklora-让「后门电路」自己现形" aria-label="Permalink to &quot;🔬 可解释的稀疏微调——TopKLoRA 让「后门电路」自己现形&quot;">​</a></h2><blockquote><p>arXiv:2610.32866 ｜ Interpretable sparse fine-tuning with TopKLoRA enables faithful circuit discovery</p></blockquote><ul><li>问题：微调常是<strong>稠密的</strong>（参数全动），导致<strong>难解释、难归因</strong>（如后门/恶意行为藏在哪条通路？）。</li><li>方法：<strong>TopKLoRA</strong> —— 在 <strong>LoRA adapters</strong> 里<strong>强制稀疏性</strong>（只激活 top-k 参数），从而让<strong>微调改动集中在少数通路</strong>上，便于<strong>电路发现（circuit discovery）</strong>。</li><li>结果：在保持微调性能的同时，使<strong>被改动的电路可被忠实定位/解释</strong>（后门注入等场景下能识别出具体通路）。</li><li>洞察：<strong>「让改变发生在少数地方」本身就是一种可解释性机制</strong> —— 与 10-23 <code>PhysiCalWorld</code>（把交互编码为少量描述符 token）、10-25「隐喻的因果子空间」同族：<strong>可解释性不一定是『事后再去解读稠密权重』，也可以是『一开始就让改动稀疏到能看懂』。</strong> 判据：<strong>当你想理解一个微调做了什么，先限制它『能改多少』。</strong></li></ul><hr><h2 id="🏢-企业-rag-要「先组织再检索」——多智能体系统缺的是知识层" tabindex="-1">🏢 企业 RAG 要「先组织再检索」——多智能体系统缺的是知识层 <a class="header-anchor" href="#🏢-企业-rag-要「先组织再检索」——多智能体系统缺的是知识层" aria-label="Permalink to &quot;🏢 企业 RAG 要「先组织再检索」——多智能体系统缺的是知识层&quot;">​</a></h2><blockquote><p>arXiv:2610.32851 ｜ Reimagining Enterprise RAG for Multi-Agent Systems: A Knowledge Layer That Organizes Before It Retrieves</p></blockquote><ul><li>问题：<strong>企业 RAG</strong> 尚未适应<strong>多智能体系统</strong>——智能体需要的是<strong>有组织、可信的知识层</strong>，而不是<strong>扁平向量库 + 临时提示</strong>（后者导致<strong>低信噪比、出处可追溯性差</strong>）。</li><li>方法：把 RAG 重构为**「先组织、再检索」的知识层** —— 先对知识做<strong>组织/结构化与溯源</strong>，再供多智能体检索使用。</li><li>结果：面向多智能体场景的知识层设计，改善<strong>信噪比与出处可追溯性</strong>（具体数值以正文为准）。</li><li>洞察：<strong>「组织」发生在「检索」之前 = 与本库 AI 外脑的核心主张同构</strong> —— 本库 <code>topics/</code>（组织层）在先、<code>query_brain</code>（检索）在后，正是这条路线；与 10-26「Enterprise 场景」、本库 <code>ai-brain</code> 的「存入即关联」一脉。<strong>判据：一个知识系统若检索质量差，第一嫌疑不是检索引擎，而是『组织层缺失』——先补组织，再调检索。</strong> 这正是本库 <code>auto_link</code> 的存在理由。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第46期 AI 板块</p></blockquote><p>关键词：科学日报第46期、HarnessMM、harness 令牌效率、decision store、留一测试准入、TerminalBench 降 14%、SWE-bench Verified 降 16%、On-Policy Self-Training、OPST、无数据自提升、on-policy、正负监督信号、指令遵循 +63%、模态鸿沟 modality gap、单纯形约束 simplex、CLIP/SigLIP、检索 +8.3%、分类 +6.5%、TopKLoRA、稀疏微调、电路发现 circuit discovery、后门定位、企业 RAG、知识层、先组织再检索、多智能体、信噪比、出处可追溯、组织层缺失先于检索引擎、准入规则、记住一个决定、负例带信息、几何约束替代数据对齐、稀疏即可解释</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-26-ai.md</code>（Accordion / 非线性概念擦除 / Ariadne）、<code>topics/ai-system-architecture/science-daily-2026-10-25-ai.md</code>（EpiSEM-Bench / METTA / 反向谄媚）、<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-brain/index.md</code></p>',26)])])}const p=r(e,[["render",i]]);export{u as __pageData,p as default};
